item.command:
/bin/zsh -c "python3 -c 'from pathlib import Path; import hashlib,re; base=Path(\"/Users/tomasz/.no-mistakes/worktrees/4019102881cf/01M2BJC44MJV1HEJ1P50949S5A/config\"); paths=[\"rialto-context-test/AGENTS.md\",\"rialto-context-test/pool/.treehouse/backend-e79957/2/backend/CLAUDE.md\",\"rialto-context-test/pool/.treehouse/backend-e79957/2/backend/AGENTS.md\",\"rialto-validation-sources/rialto-backend/CLAUDE.md\",\"rialto-validation-sources/rialto-backend/AGENTS.md\",\"rialto-validation-sources/rialto-frontend/CLAUDE.md\",\"rialto-validation-sources/rialto-frontend/AGENTS.md\",\"rialto-validation-sources/AGENTS.md\"];
for rel in paths:
 p=base/rel; print(\"SOURCE\",rel)
 try:
  b=p.read_bytes(); print(\"SHA-256\",hashlib.sha256(b).hexdigest()); lines=b.decode().splitlines(); hits=set()
  for i,line in enumerate(lines):
   if re.search(\"validation.marker|recovery|compaction|CONTEXT_DELIVERY|canary\",line,re.I): hits.update(range(max(0,i-2),min(len(lines),i+5)))
  for i in sorted(hits): print(str(i+1)+\": \"+lines[i])
  if len(lines)<150: print(\"FULL TEXT\\n\"+b.decode())
 except OSError as e: print(type(e).__name__,str(e))'"

